s = s.replace("let s;try{s=restore(localStorage.getItem(KEY));}catch{s=freshState();}", "let s,storageHealthy=true;try{s=restore(localStorage.getItem(KEY));}catch{s=freshState();storageHealthy=false;}")
s = s.replace('function save(){try{localStorage.setItem(KEY,JSON.stringify(s));const e=$(\'#save-status\');if(e)e.textContent=\'이 기기에 저장됨\';}catch{const e=$(\'#save-status\');if(e)e.textContent=\'저장 공간 부족 · 현재 창에서 계속 가능\';}}', "function saveLabel(){return storageHealthy?'이 기기에 자동 저장됨':'저장 불가 · 창을 닫기 전 결과를 저장해줘';}\nfunction save(){try{localStorage.setItem(KEY,JSON.stringify(s));storageHealthy=true;}catch{storageHealthy=false;}const e=$('#save-status');if(e){e.textContent=saveLabel();e.classList.toggle('save-error',!storageHealthy);}}")
