s = s.replace("function modal(content){$('#modal').innerHTML=`${button('닫기 ×','close','close')}<div class=\"modal-body\">${content}</div>`;$('#modal').showModal();}", "let modalReturnFocus;\nfunction modal(content){modalReturnFocus=document.activeElement;const dialog=$('#modal');dialog.innerHTML=`${button('닫기 ×','close','close','aria-label=\"창 닫기\"')}<div class=\"modal-body\">${content}</div>`;const heading=dialog.querySelector('h2');if(heading){heading.id='dialog-title';dialog.setAttribute('aria-labelledby','dialog-title');}else dialog.setAttribute('aria-label','연구 안내');if(!dialog.open)dialog.showModal();}")
s = s.replace("const focus=same?document.activeElement?.dataset?.field:null;", "const active=document.activeElement;\n const focus=same&&active&&!active.closest('dialog')?{field:active.dataset.field,action:active.dataset.action,id:active.dataset.id}:null;")
s = s.replace("if(focus){const e=document.querySelector('[data-field=\"'+focus+'\"]');e?.focus({preventScroll:true});}", "if(focus){let e;if(focus.field)e=document.querySelector('[data-field=\"'+focus.field+'\"]');else if(focus.action)e=document.querySelector('[data-action=\"'+focus.action+'\"]'+(focus.id!==undefined?'[data-id=\"'+focus.id+'\"]':''));(e||document.querySelector('main h1'))?.focus({preventScroll:true});}\n if(!same&&!$('#modal').open){const heading=document.querySelector('main h1');heading?.setAttribute('tabindex','-1');heading?.focus({preventScroll:true});}")
s = s.replace("background-image:url('assets/scene-${String(n+1).padStart(2,'0')}.png')", "background-image:url('${SCENES[n]}')")
