s = s.replace('<small>${n===0?\'Evidence 01 · 변화 관찰 기록\':\'나의 탐구 기록\'}</small>', '<small>나의 탐구 기록</small>')
s = s.replace('<div class="note-heading">${icon(\'book\')}<span>FIELD NOTES', '<div class="note-heading">${icon(\'book\')}<span>RESEARCH NOTE')
s = s.replace('${s.comparisons.filter(c=>c.kind===kind).reduce((sum,c)=>sum+c.notes.length,0)} / 2 기준', '${Math.min(2,Math.max(0,...s.comparisons.filter(c=>c.kind===kind).map(c=>c.notes.length)))} / 2 기준')
s = s.replace('두 생물의 모습과 설명을 읽고, 기준을 바꾸며 기록해 줘.', '같은 동물 한 쌍과 같은 식물 한 쌍에서 서로 다른 기준을 2개씩 기록해 줘.')

def replace_function(name, body):
    global s
    pattern = r'^function ' + re.escape(name) + r'\([^\n]*\n?'
    match = re.search(pattern, s, re.M)
    if not match:
        raise ValueError(name)
    s = s[:match.start()] + body.rstrip() + '\n' + s[match.end():]

replace_function('controls', '''function controls(which,keys){
 const e=s[which],locked=s.completed.includes(which==='seed'?2:4)&&!experimentIssue(e,keys);
 return `<div class="condition-grid">${['a','b'].map((slot,i)=>`<div class="condition-card"><div class="sample-badge ${slot}">${slot.toUpperCase()} <small>${i?'비교 화분':'기준 화분'}</small></div><div class="condition-art">${plant(which==='seed'?0:3,false)}${which==='green'?assetImage(e[slot].light?'lamp':'shade',e[slot].light?'빛이 충분한 환경':'빛을 가린 환경','environment-tool'):''}</div>${keys.map(k=>`<label>${k==='water'?'물':k==='warm'?'온도':'햇빛'}<select data-field="${which}.${slot}.${k}" data-bool ${locked?'disabled':''}><option value="true" ${e[slot][k]?'selected':''}>${k==='water'?'적당히 줌':k==='warm'?'알맞음':'충분함'}</option><option value="false" ${!e[slot][k]?'selected':''}>${k==='water'?'주지 않음':k==='warm'?'낮음':'부족함'}</option></select></label>`).join('')}</div>`).join('')}</div>`;
}''')
replace_function('question', '''function question(which){const isSeed=which==='seed',e=s[which],keys=isSeed?['water','warm']:['light','water'];return `<label class="question-label">오늘의 실험 질문<select data-field="${which}.question" ${s.completed.includes(isSeed?2:4)&&!experimentIssue(e,keys)?'disabled':''}><option value="${isSeed?'water':'light'}" ${e.question===(isSeed?'water':'light')?'selected':''}>${isSeed?'씨가 싹트는 데 물이 필요할까?':'식물이 잘 자라는 데 햇빛이 필요할까?'}</option><option value="${isSeed?'warm':'water'}" ${e.question===(isSeed?'warm':'water')?'selected':''}>${isSeed?'씨가 싹트는 데 알맞은 온도가 필요할까?':'식물이 잘 자라는 데 물이 필요할까?'}</option></select></label>`;}''')
replace_function('experiment', '''function experiment(){const issue=experimentIssue(s.seed,['water','warm']);return `<div class="paper-work">${question('seed')}${controls('seed',['water','warm'])}<div class="constant-strip">${icon('check')} 같은 강낭콩 씨 3개 · 같은 용기 · 같은 관찰 시간</div><div class="validation ${!issue?'valid':''}" role="status">${issue==='baseline'?'비교할 수 있도록 나머지 조건은 두 화분 모두 알맞게 맞춰줘.':issue?'A와 B에서 알아볼 조건 하나만 다르게 해줘.':'✓ 공정한 비교 준비 완료! 시간에 따른 변화를 관찰하러 가자.'}</div></div>`;}''')
replace_function('vessels', '''function vessels(){const e=s.seedRun||s.seed;return ['a','b'].map(slot=>{const level=seedLevel(e[slot],s.day);return `<div class="vessel"><span class="sample-badge ${slot}">${slot.toUpperCase()} <small>${slot==='a'?'기준 화분':'비교 화분'}</small></span><div class="plant-drawing">${plant(level,transparent)}</div><span class="vessel-condition">${conditionText(e,slot)}</span><b>${['아직 싹이 보이지 않아','작은 뿌리가 나왔어','줄기와 떡잎이 보여','싹과 잎이 자라고 있어'][level]}</b></div>`;}).join('');}''')
replace_function('simulation', '''function simulation(){return `<div class="sim-work"><span class="scene-label">시간에 따른 변화 <b id="day-label">${s.day}일</b></span><div class="vessels" id="vessels">${vessels()}</div><div class="time-console">${assetImage('lever','','lever-art')}<div class="time-controls"><label for="day">시간을 움직여 관찰해 봐 <b id="day-number">${s.day}일</b></label><input id="day" type="range" min="0" max="7" value="${s.day}" data-field="day" data-number><div class="range-labels"><span>실험 시작</span><span>7일</span></div><div class="row">${button(icon('pin')+' 지금 모습 저장','snapshot','primary')}${button(transparent?'✓ 흙 속 보기':'흙 속 보기','soil','',`aria-pressed="${transparent}"`)}</div></div></div><p class="sim-disclaimer">교육용 모형이야. 실제 발아 시간은 환경과 개체에 따라 달라.</p></div>`;}''')
replace_function('greenhouse', '''function greenhouse(){const issue=experimentIssue(s.green,['water','light']);return `<div class="paper-work compact">${question('green')}<div class="sensor-rack">${[['light','lightSensor','빛 센서'],['water','moistureSensor','수분 센서']].map(([id,key,label])=>button(assetImage(key,'','sensor-art')+`<span>${label}<small>${s.green.sensors.includes(id)?'✓ 두 화분에 설치됨':'눌러서 설치하기'}</small></span>`,'sensor',s.green.sensors.includes(id)?'selected':'',`data-id="${id}" aria-pressed="${s.green.sensors.includes(id)}"`)).join('')}</div>${controls('green',['light','water'])}<div class="validation ${!issue&&s.green.sensors.length===2?'valid':''}" role="status">${s.green.sensors.length<2?'빛 센서와 수분 센서를 모두 설치해줘.':issue==='baseline'?'나머지 조건은 두 화분 모두 알맞게 맞춰줘.':issue?'알아볼 조건 하나만 다르게 맞춰줘.':'✓ 센서와 조건 준비 완료! 두 식물의 성장을 비교하러 가자.'}</div></div>`;}''')
replace_function('ending', '''function ending(){const finished=s.completed.includes(9)&&ready(s,8);return `<div class="ending-work"><div class="ending-title"><span class="eyebrow">THE LIFE CLOCK</span><h2>${finished?'숲의 시간이 다시 흐르기 시작했어!':'다섯 발견으로 시계를 깨워 줘'}</h2><p>${finished?'작은 생명의 변화를 발견한 너는 생명 연구원이야.':'아래 링을 눌러 네가 남긴 연구 기록을 돌려줘.'}</p></div><div class="clock-display ${s.rings.length===5?'is-awake':''}">${assetImage('clock','','clock-body')}${assetImage('core','','clock-core')}<span class="clock-progress">${s.rings.length} / 5</span></div><div class="clock-rings">${['관찰','발아','성장','다양성','기록'].map((r,i)=>button(`${assetImage('ring','','ring-art')}<span>${s.rings.includes(i)?icon('check'):icon(['lens','drop','sun','leaf','book'][i])}</span><b>${r}</b>`,'ring',`clock-ring ${s.rings.includes(i)?'restored':''}`,`data-id="${i}" aria-pressed="${s.rings.includes(i)}"`)).join('')}</div>${!ready(s,8)?`<div class="ending-repair">소개 자료를 완성하면 시계를 깨울 수 있어.${button('내 자료 완성하기','repair-artifact','quiet')}</div>`:''}<div class="ending-actions">${button(icon('book')+' 내 소개 자료 보기','preview','quiet')}${button(icon('download')+' 결과 카드 저장','export','',ready(s,8)?'':'disabled')}</div></div>`;}''')
s = s.replace("case 'finish-map':", "case 'repair-artifact':go(8);break;\n case 'finish-map':")
s = s.replace("else if(n%2===1){go('map');toast(`${missions[n][2]} 링을 되찾았어! 다음 연구 구역이 열렸어.`);}", "else if(n%2===1){go('map');const reward=['모습이 변하는 증거를 찾아냈어.','조건을 하나만 바꿔 발아를 비교했어.','관찰 결과를 근거로 설명했어.','서로 다른 생물의 한살이를 비교했어.'][Math.floor(n/2)];modal(`<div class=\"stage-reward\">${assetImage('ring','','reward-ring')}<span class=\"eyebrow\">연구 기록 복구 완료</span><h2>${missions[n][2]} 링을 되찾았어!</h2><p>${reward}</p><p>네 기록은 마지막 생명 이야기의 재료가 돼.</p>${button('다음 연구 구역 살펴보기','close','primary')}</div>`);}")
s = s.replace("try{const cv=document.createElement('canvas'),rows=", "try{const cv=document.createElement('canvas'),rows=")
s = s.replace("const img=new Image();await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=reject;img.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(sceneArt(a));});", "const svg=await embedArtworkImages(sceneArt(a));const img=new Image();await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=reject;img.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(svg);});")
s = s.replace("$('#modal').addEventListener('click'", "$('#modal').addEventListener('close',()=>{if(modalReturnFocus?.isConnected)modalReturnFocus.focus({preventScroll:true});else document.querySelector('main h1')?.focus({preventScroll:true});});\n$('#modal').addEventListener('click'")
s = s.replace('초등 3학년 「생물의 한살이」 보조 탐구 MVP입니다.', '초등 3학년 「생물의 한살이」 보조 탐구 학습입니다.')
